from typing import List
from collections import defaultdict

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        events = defaultdict(int)
        total_area = 0

        for _, y, l in squares:
            total_area += l * l
            events[y] += l
            events[y + l] -= l

        target_twice = total_area
        area_twice = 0
        active_width = 0
        prev_y = None

        for y in sorted(events):
            if prev_y is not None and y > prev_y and active_width > 0:
                gained_twice = 2 * (y - prev_y) * active_width
                if area_twice + gained_twice >= target_twice:
                    return prev_y + (target_twice - area_twice) / (2.0 * active_width)
                area_twice += gained_twice

            active_width += events[y]
            prev_y = y

        return float(prev_y)
